from lib import Svg, figure

def pipeline():
    g = Svg(1500, 640, "gw", "3b")
    g.node(40, 26, 1000, 60, "NATS JetStream: BLOODBANK_COMMANDS (workqueue) + BLOODBANK_EVENTS", "[external container]", [], "ext")
    g.zone(20, 104, 740, 170, "BloodbankAdapter lanes", "zone solid")
    g.node(40, 140, 330, 120, "Interactive lane", "[component: LaneRuntime, filter invoke]", ["consumer bloodbank-hermes-gateway-interactive", "max_ack_pending 2, max_deliver 8, nak 3 s,", "ack_wait 180 s; memos only; turn wall clock ON"], "component", accent=True)
    g.node(410, 140, 330, 120, "Batch lane", "[component: LaneRuntime, filter start]", ["consumer bloodbank-hermes-gateway", "max_ack_pending 4, max_deliver 5;", "n8n grooming + PMs; no turn limit by default"], "component")
    g.node(790, 140, 220, 100, "Progress ack", "[component: heartbeat]", ["in-progress ack every 30 s so", "a long turn is never redelivered"], "component")
    g.zone(20, 296, 1110, 150, "shared handler", "zone solid", dx=720)
    g.node(40, 340, 160, 90, "decode_command", "[contract.py]", ["envelope + lane type;", "data.deadline_seconds;", "poison -> term"], "component")
    g.node(240, 340, 170, 90, "Execution journal", "[SQLite, WAL]", ["claim row: pending ->", "started; lane column;", "replay if completed"], "component")
    g.node(450, 340, 170, 90, "Dispatch", "[adapter.py]", ["per-conversation lock", "profile:thread_id;", "MessageEvent(internal)"], "component")
    g.node(660, 340, 210, 90, "Turn wall clock", "[_await_turn]", ["wait_for(shield(completion),", "min(deadline, lane limit))"], "component", accent=True)
    g.node(910, 340, 200, 90, "Lifecycle publisher", "[adapter.py]", ["invocation.started / completed /", "failed (data.lane);", "conversation.turn.*"], "component")
    g.node(450, 520, 230, 90, "Hermes runner", "[container: in-process]", ["handle_message, per-session", "turn lease; /stop path"], "container")
    g.node(760, 520, 230, 90, "Agent turn", "[profile: holocene-pm etc.]", ["model loop + tools + shell;", "state.db session = memo_id"], "container")
    g.node(1180, 140, 290, 210, "Config (gateway.platforms.bloodbank.extra)", "[~/.hermes/config.yaml]", ["interactive.turn_timeout_seconds:", "  default 300; strict number,", "  0 < x <= 86400, else the", "  adapter refuses to start", "batch turn_timeout_seconds:", "  optional, default none", "envelope data.deadline_seconds", "  can only shorten the limit"], "container")
    # edges
    g.edge([(205,86),(205,140)]); g.label(213,118,"pull .invoke",anchor="start")
    g.edge([(575,86),(575,140)]); g.label(583,118,"pull .start",anchor="start")
    g.edge([(870,140),(870,86)]); g.label(878,118,"ack progress",anchor="start")
    g.edge([(120,260),(120,340)])
    g.edge([(575,260),(575,300),(190,300),(190,340)])
    g.edge([(200,385),(240,385)])
    g.edge([(410,385),(450,385)])
    g.edge([(620,385),(660,385)]); g.label(640,374,"await",anchor="middle")
    g.edge([(870,385),(910,385)]); g.label(890,374,"done",anchor="middle")
    g.edge([(1010,340),(1010,86)]); g.label(1018,214,"facts + ack",anchor="start")
    g.edge([(535,430),(535,520)]); g.label(543,480,"handle_message",anchor="start")
    g.edge([(680,565),(760,565)]); g.label(720,556,"turn",anchor="middle")
    g.edge([(790,520),(790,430)], "dash"); g.label(798,480,"completion future",anchor="start")
    g.note(40, 640 - 8, "Same handler for both lanes; only the LaneRuntime differs. A lane slot is held from fetch until the turn resolves and the message is acked.")
    svg = g.render("Hermes gateway bloodbank plugin components", "Two lane runtimes feed one shared handler: decode, journal claim, dispatch into Hermes, the per-turn wall clock, lifecycle facts and ack.")
    pre = '<h2 id="l3b">Level 3b: components, the Hermes gateway plugin</h2><p class="lede">Two JetStream consumers, one handler. The interactive lane is the voice lane: 2 slots, and since today a wall clock on every turn. The batch lane keeps its 4 slots and runs long grooming turns unbounded unless configured.</p>'
    return pre + figure(svg, "The adapter lives inside the single multiplexed hermes-gateway.service (restart is about two minutes of reconnect and interrupts in-flight turns, so it only restarts when both consumers show ack_pending 0).")

def timeout():
    g = Svg(1300, 600, "timeout", "3c")
    g.zone(8, 20, 1284, 470, "BloodbankAdapter, one lane (interactive shown): what happens when a turn outlives its budget")
    g.node(30, 70, 170, 90, "consume loop", "[pull fetch]", ["slots = max_inflight 2", "supervised, resumes"], "component")
    g.node(240, 70, 170, 90, "decode_command", "", ["envelope + lane type", "data.deadline_seconds"], "component")
    g.node(450, 70, 170, 90, "journal claim", "[SQLite]", ["pending -> started", "replay if completed"], "component")
    g.node(660, 70, 170, 90, "dispatch", "", ["conversation lock", "handle_message()"], "component")
    g.node(870, 70, 190, 90, "_await_turn", "[wall clock]", ["wait_for(shield(completion),", "min(deadline, lane limit))"], "component", accent=True)
    g.node(1130, 70, 150, 90, "on_processing_complete", "[Hermes hook]", ["success / failure /", "cancelled"], "component")
    g.node(870, 230, 190, 80, "1 claim outcome", "", ["finalizing = true;", "late hooks stand down"], "component", accent=True)
    g.node(660, 230, 170, 80, "2 stop the turn", "", ["inject /stop for the session;", "turn_stopped = true|false"], "component", accent=True)
    g.node(450, 230, 170, 80, "3 close journal", "", ["completed / failure /", "failure_code=turn_timeout"], "component", accent=True)
    g.node(240, 230, 170, 80, "4 publish + ack", "", ["invocation.failed,", "turn.completed(failed); ack"], "component", accent=True)
    g.node(30, 230, 170, 80, "5 slot free", "", ["handler returns;", "next fetch pulls"], "component", accent=True)
    g.node(660, 390, 220, 70, "Hermes runner", "[container]", ["/stop: hard interrupt, bump run", "generation, kill spawned shells"], "container")
    g.node(980, 390, 200, 70, "agent turn", "[tool call, model loop]", ["interrupted"], "container")
    for a,b in [((200,115),(240,115)),((410,115),(450,115)),((620,115),(660,115)),((830,115),(870,115))]:
        g.edge([a,b])
    g.edge([(1130,115),(1060,115)], "dash"); g.label(1095,90,"completes|in time",anchor="middle")
    g.edge([(965,160),(965,230)], "accent"); g.label(973,200,"budget expired",anchor="start",cls="accent")
    for a,b in [((870,270),(830,270)),((660,270),(620,270)),((450,270),(410,270)),((240,270),(200,270))]:
        g.edge([a,b], "accent")
    g.edge([(745,310),(745,390)], "accent"); g.label(753,355,"/stop",anchor="start",cls="accent")
    g.edge([(880,425),(980,425)], "accent"); g.label(930,416,"interrupt",anchor="middle",cls="accent")
    g.note(30, 520, "Normal path: _await_turn returns when Hermes calls on_processing_complete; the same code journals success or failure and acks.")
    g.note(30, 540, "Why this order: the journal is written before publishing, so a failed publish replays identical events on redelivery and never re-runs the prompt.")
    g.note(30, 560, "Honest limit: a tool call blocked in a thread that ignores interrupts can outlive the stop; the fact then says turn_stopped=false and the slot is still freed.")
    svg = g.render("Per-turn wall clock timeout path", "When a turn outlives its budget the adapter claims the outcome, stops the Hermes turn, closes the journal, publishes the failed fact, acks and frees the slot.")
    pre = '<h3 style="margin-top:34px">Level 3c: the timeout path, step by step</h3>'
    return pre + figure(svg, "Proved live: a sleep 1000 voice memo was stopped at 300.1 s (process killed, exit -15), the journal closed turn_timeout, and /voice showed &ldquo;Agent turn timed out after 300s&rdquo;. Two hung turns plus a third command: the third started 37 ms after the first slot closed.")

def html():
    return pipeline() + timeout()
